 	N8nActionToggle,
 	N8nIcon,
 	N8nIconButton,
-	N8nRadioButtons,
+	N8nSegmentControl,
 	N8nText,
 } from '@n8n/design-system';
 interface Props {
 	parameter: INodeProperties;
 	isReadOnly: boolean;
 	value: NodeParameterValueType;
 	showOptions?: boolean;
 	showExpressionSelector?: boolean;
 	showFocusPanel?: boolean;
 	customActions?: Array<{ label: string; value: string; disabled?: boolean }>;
 	iconOrientation?: 'horizontal' | 'vertical';
 	loading?: boolean;
 	loadingMessage?: string;
 	isContentOverridden?: boolean;
 	showDelete?: boolean;
 	onDelete?: () => void;
 }

 const props = withDefaults(defineProps<Props>(), {
 	showOptions: true,
 	showExpressionSelector: true,
 	showFocusPanel: true,
 	customActions: () => [],
 	iconOrientation: 'vertical',
 	loading: false,
 	loadingMessage: () => useI18n().baseText('genericHelpers.loading'),
 	isContentOverridden: false,
 	showDelete: false,
 	onDelete: undefined,
 });

 const emit = defineEmits<{
