 				@update:model-value="onViewSelected"
 			/>

 			<N8nIconButton
 				variant="ghost"
 				v-if="showDelete && onDelete"
 				size="small"
 				icon-size="large"
 				icon="trash-2"
 				:class="$style.deleteButton"
 				:title="i18n.baseText('parameterInputList.delete')"
